import XCTest
import EventKit
@testable import WaypointKit

class CalendarExportServiceTests: XCTestCase {

    var calendarExportService: CalendarExportService!
    var eventStore: EKEventStore!

    override func setUp() {
        super.setUp()
        eventStore = EKEventStore()
        calendarExportService = CalendarExportService()
    }

    func testExportDay_permissionDenied() async throws {
        let day = Day(id: UUID(), date: Date(), trip: nil, stops: [])
        eventStore.authorizationStatus(for: .event) = .denied

        let result = try await calendarExportService.exportDay(day, context: ModelContext())

        XCTAssertEqual(result.created, 0)
        XCTAssertEqual(result.updated, 0)
        XCTAssertEqual(result.outcome, .permissionDenied)
    }

    func testExportDay_permissionRestricted() async throws {
        let day = Day(id: UUID(), date: Date(), trip: nil, stops: [])
        eventStore.authorizationStatus(for: .event) = .restricted

        let result = try await calendarExportService.exportDay(day, context: ModelContext())

        XCTAssertEqual(result.created, 0)
        XCTAssertEqual(result.updated, 0)
        XCTAssertEqual(result.outcome, .permissionRestricted)
    }

    func testExportDay_success() async throws {
        let day = Day(id: UUID(), date: Date(), trip: nil, stops: [
            Stop(id: UUID(), day: Day(id: UUID(), date: Date(), trip: nil, stops: []), sortIndex: 0, name: "Stop1", address: "", latitude: nil, longitude: nil, startTime: Date(), endTime: nil, notes: "", category: .food, isCheckedOff: false, calendarEventIdentifier: nil)
        ])
        eventStore.authorizationStatus(for: .event) = .authorized

        let result = try await calendarExportService.exportDay(day, context: ModelContext())

        XCTAssertEqual(result.created, 1)
        XCTAssertEqual(result.updated, 0)
        XCTAssertEqual(result.outcome, .success)
    }

    func testExportDay_existingEventUpdated() async throws {
        let day = Day(id: UUID(), date: Date(), trip: nil, stops: [
            Stop(id: UUID(), day: Day(id: UUID(), date: Date(), trip: nil, stops: []), sortIndex: 0, name: "Stop1", address: "", latitude: nil, longitude: nil, startTime: Date(), endTime: nil, notes: "", category: .food, isCheckedOff: false, calendarEventIdentifier: "existingEventID")
        ])
        eventStore.authorizationStatus(for: .event) = .authorized

        let result = try await calendarExportService.exportDay(day, context: ModelContext())

        XCTAssertEqual(result.created, 0)
        XCTAssertEqual(result.updated, 1)
        XCTAssertEqual(result.outcome, .success)
    }

    func testExportDay_permissionError() async throws {
        let day = Day(id: UUID(), date: Date(), trip: nil, stops: [])
        eventStore.authorizationStatus(for: .event) = .denied

        do {
            _ = try await calendarExportService.exportDay(day, context: ModelContext())
        } catch {
            XCTAssertEqual((error as NSError).domain, "Waypoint")
            XCTAssertEqual((error as NSError).code, -1)
        }
    }

    func testExportDay_saveError() async throws {
        let day = Day(id: UUID(), date: Date(), trip: nil, stops: [
            Stop(id: UUID(), day: Day(id: UUID(), date: Date(), trip: nil, stops: []), sortIndex: 0, name: "Stop1", address: "", latitude: nil, longitude: nil, startTime: Date(), endTime: nil, notes: "", category: .food, isCheckedOff: false, calendarEventIdentifier: nil)
        ])
        eventStore.authorizationStatus(for: .event) = .authorized

        do {
            _ = try await calendarExportService.exportDay(day, context: ModelContext())
        } catch {
            XCTAssertEqual((error as NSError).domain, "Waypoint")
            XCTAssertEqual((error as NSError).code, -2)
        }
    }

}
